;; Five inheritance modes and four transform modes match runtime matrices, including reflections and shear.
(deftest affine-and-transform-oracle-test
  (doseq [{:keys [name bones constraints expected]} oracle-cases]
    (let [actual (:transforms (editor.skeletal-animation-constraints/evaluate bones constraints))]
      (doseq [[bone expected] (mapv vector bones expected)
              [a b] (mapv vector (get actual (:id bone)) expected)]
        (is (< (abs (- (double a) (double b))) 1.0e-4) (str name "/" (:id bone)))))))

;; Invalid hierarchies, inheritance, feedback and nonfinite inputs fail at the boundary.
(deftest malformed-constraints-test
  (doseq [bones [[{:id "a" :parent "missing"}]
                 [{:id "a" :parent "b"} {:id "b" :parent "a"}]
                 [{:id "a" :inherit "wrong"}]
                 [{:id "a" :x ##NaN}]]]
    (is (thrown? clojure.lang.ExceptionInfo (constraints/world-transforms bones))))
  (is (thrown? clojure.lang.ExceptionInfo
               (constraints/evaluate [{:id "root"} {:id "child" :parent "root"}]
                                     [{:id "loop" :bones ["root"] :target "child"}]))))

;; Disabled constraints are exact no-ops; collapsed parent axes never emit nonfinite vertices.
(deftest disabled-and-singular-constraint-test
  (let [bones [{:id "root" :scale-x 0.0 :scale-y 2.0} {:id "child" :parent "root" :inherit "noScale"}]
        pose (constraints/pose bones)
        constraint (merge {:id "off" :bones ["child"] :target "root"}
                          (zipmap (mapv keyword constraints/transform-properties) (repeat 6 0.0)))]
    (is (= pose (constraints/apply-transform-constraint pose constraint)))
    (is (coll/every? #(Double/isFinite (double %)) (get-in pose [:transforms "child"])))))

