;; Independent IK geometry matches official 4.2 reference matrices across softness, stretch, compression, inheritance, and earlier transform constraints.
(deftest full-ik-oracle-test
  (doseq [{:keys [name bones constraints ik expected]} ik-oracle-cases]
    (let [initial (editor.skeletal-animation-constraints/evaluate bones constraints)
          actual (:transforms (reduce editor.skeletal-animation-constraints/apply-ik-constraint initial ik))]
      (doseq [[bone expected] (mapv vector bones expected)
              [a b] (mapv vector (get actual (:id bone)) expected)]
        (is (< (abs (- (double a) (double b))) 1.0e-3) (str name "/" (:id bone)))))))

;; Zero-length and collapsed chains remain finite, and zero mix preserves the entire pose exactly.
(deftest degenerate-ik-test
  (let [bones [{:id "root" :scale-x 0.0} {:id "upper" :parent "root" :length 0.0}
               {:id "lower" :parent "upper" :length 0.0} {:id "target" :parent "root" :x 100.0 :y 80.0}]
        pose (constraints/pose bones)
        ik {:id "ik" :bones ["upper" "lower"] :target "target" :softness 20.0 :stretch true}]
    (is (= pose (constraints/apply-ik-constraint pose (assoc ik :mix 0.0))))
    (doseq [matrix (into [] (coll/vals (:transforms (constraints/apply-ik-constraint pose ik)))) value matrix]
      (is (Double/isFinite (double value))))))

