;; Path curves match Spine 4.2 reference matrices for open/closed, weighted/deformed, negative spacing, and mixed transforms.
(deftest path-constraint-oracle-test
  (doseq [{:keys [name bones slot constraint deform expected]} path-oracle-cases]
    (let [actual (:transforms (constraints/apply-path-constraint (constraints/pose bones) constraint slot (or deform [])))]
      (doseq [[bone expected] (mapv vector bones expected)
              [a b] (mapv vector (get actual (:id bone)) expected)]
        (is (< (abs (- (double a) (double b))) 1.0e-3) (str name "/" (:id bone)))))))

;; Missing visible path attachments and zero mixes are exact no-ops; collapsed curves and zero bone lengths stay finite.
(deftest path-degenerate-pose-test
  (let [bones [{:id "root"} {:id "bone" :parent "root" :length 0.0 :scale-x 0.0}]
        pose (constraints/pose bones)
        constraint {:id "path" :bones ["bone"] :target "slot" :rotate-mode "chainScale"}
        slot {:id "slot" :bone "root" :attachment {:type "path" :vertices (vec (repeat 12 0.0)) :closed false :constant-speed true :lengths [0.0]}}]
    (is (= pose (constraints/apply-path-constraint pose constraint (dissoc slot :attachment) [])))
    (is (= pose (constraints/apply-path-constraint pose (assoc constraint :mix-rotate 0.0 :mix-x 0.0 :mix-y 0.0) slot [])))
    (doseq [matrix (into [] (coll/vals (:transforms (constraints/apply-path-constraint pose constraint slot [])))) value matrix]
      (is (Double/isFinite (double value))))
    (is (= [0.0] (constraints/path-lengths (:attachment slot) (get-in pose [:transforms "root"]) (:transforms pose))))))
